const RULE_TOKENS_BY_PACK_RE = /rule tokens by pack:\\s*([^\\n,]+)/;
const PACK_TOKENS_RE = /^\\s*([A-Za-z0-9][A-Za-z0-9_-]*)\\s+([\\d,]+)\\s*\\.?\\s*$/;

export function ruleTokensByPackIn(text) {
  const m = RULE_TOKENS_BY_PACK_RE.exec(String(text ?? ''));
